releases.manifests:
apiVersion: cert-manager.io/v1
kind: Issuer
metadata: {name: crowdsec-selfsigned, namespace: crowdsec}
spec: {selfSigned: {}}
---
apiVersion: cert-manager.io/v1
kind: Certificate
metadata: {name: crowdsec-ca, namespace: crowdsec}
spec:
  isCA: true
  commonName: crowdsec-ca
  secretName: crowdsec-ca
  # Ten years, like the certificates it signs.
  duration: 87600h
  renewBefore: 720h
  privateKey: {algorithm: ECDSA, size: 256}
  issuerRef: {name: crowdsec-selfsigned, kind: Issuer}
---
apiVersion: cert-manager.io/v1
kind: Issuer
metadata: {name: crowdsec-ca, namespace: crowdsec}
spec:
  ca: {secretName: crowdsec-ca}

profiles.multi-node:
agent:
  resources:
    # One agent per node; busier logs than single-node.
    requests: {cpu: 50m, memory: 64Mi}
    limits: {memory: 256Mi}
lapi:
  resources:
    # Headroom for more agents and decisions.
    requests: {cpu: 50m, memory: 96Mi}
    limits: {memory: 384Mi}

profiles.single-node:
agent:
  resources:
    # Chart asks 250Mi; an idle agent uses under 100Mi.
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 192Mi}
lapi:
  resources:
    # Chart asks 500Mi; LAPI on SQLite idles far below.
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}
